373		// One pair of square brackets must wrap the whole host: after the
374		// closing ']' only the optional port (":" plus digits) may follow before
375		// the base path. A valid first literal never legitimizes a repeated
376		// bracket group, a stray ']', text between the address and the port, or
377		// non-port bytes — with or without userinfo. Every such upstream rejects
378		// the whole configuration as invalid_config with a content reason naming
379		// the route position, its id and the upstream field, never as broken
380		// JSON.
381		badUpstreams := []struct {
382			name     string
383			upstream string
384		}{
385			{"repeated bracket group", "http://[::1][::2]/v1"},
386			{"text and a stray closing bracket", "http://[::1]extra]/v1"},
387			{"stray closing bracket", "http://[::1]]/v1"},
388			{"repeated bracket group before a port", "http://[::1][::2]:8080/v1"},
389			{"repeated bracket group after a port", "http://[::1]:8080[::2]/v1"},
390			{"bare text after the closing bracket", "http://[::1]extra/v1"},
391			{"digits after the bracket without a colon", "http://[::1]8080/v1"},
392			{"non digit bytes in the port", "http://[::1]:80a/v1"},
393			{"extra colon group in the port", "http://[::1]:80:80/v1"},
394			{"userinfo with a repeated bracket group", "http://user:pw@[::1][::2]/v1"},
395			{"encoded userinfo with text and a stray bracket", "https://user:p%40ss@[::1]extra]/v1"},
