func TestInvalidConfigBracketedHostShape(t *testing.T) {
	// One pair of square brackets must wrap the whole host: after the
	// closing ']' only the optional port (":" plus digits) may follow before
	// the base path. A valid first literal never legitimizes a repeated
	// bracket group, a stray ']', text between the address and the port, or
	// non-port bytes — with or without userinfo. Every such upstream rejects
	// the whole configuration as invalid_config with a content reason naming
	// the route position, its id and the upstream field, never as broken
	// JSON.
	badUpstreams := []struct {
		name     string
		upstream string
	}{
		{"repeated bracket group", "http://[::1][::2]/v1"},
		{"text and a stray closing bracket", "http://[::1]extra]/v1"},
		{"stray closing bracket", "http://[::1]]/v1"},
		{"repeated bracket group before a port", "http://[::1][::2]:8080/v1"},
		{"repeated bracket group after a port", "http://[::1]:8080[::2]/v1"},
		{"bare text after the closing bracket", "http://[::1]extra/v1"},
		{"digits after the bracket without a colon", "http://[::1]8080/v1"},
		{"non digit bytes in the port", "http://[::1]:80a/v1"},
		{"extra colon group in the port", "http://[::1]:80:80/v1"},
		{"userinfo with a repeated bracket group", "http://user:pw@[::1][::2]/v1"},
		{"encoded userinfo with text and a stray bracket", "https://user:p%40ss@[::1]extra]/v1"},
		{"encoded userinfo with junk after the port", "https://user:p%40ss@[::1]:8443x/v1"},
		{"userinfo with a second bracket group after the port", "http://u@[::1]:8080[::2]/v1"},
	}
	for _, tc := range badUpstreams {
		t.Run(tc.name, func(t *testing.T) {
			src := `{"routes":[
			  {"id":"api","methods":["GET"],"pathPrefix":"/api","upstream":"http://api.internal/v1"},
			  {"id":"admin","methods":["GET"],"pathPrefix":"/admin","upstream":"` + tc.upstream + `"}
			]}`
			cfg, f := ParseConfig([]byte(src))
			if f == nil {
				t.Fatalf("expected invalid_config for upstream %q", tc.upstream)
			}
			if f.Code != "invalid_config" {
				t.Fatalf("code = %q, want invalid_config", f.Code)
			}
			for _, want := range []string{"route 2", `"admin"`, "upstream", "bracketed host", "IPv6"} {
				if !strings.Contains(f.Reason, want) {
					t.Fatalf("reason = %q, want substring %q", f.Reason, want)
				}
			}
			if strings.Contains(f.Reason, "not valid JSON") {
				t.Fatalf("a bad bracketed host shape is a content error, not a JSON syntax failure: %q", f.Reason)
			}
			if cfg != nil {
				t.Fatalf("a rejected config must not be returned, got %+v", cfg)
			}
		})
	}

	// The offending route may be one the request never hits: config
	// validation still fails up front (and hands back no config at all)
	// instead of letting the first, valid route resolve the request.
	for _, up := range []string{"http://[::1][::2]/v1", "http://[::1]extra]/v1"} {
		src := `{"routes":[
		  {"id":"api","methods":["GET"],"pathPrefix":"/api","upstream":"http://api.internal/v1"},
		  {"id":"admin","methods":["GET"],"pathPrefix":"/admin","upstream":"` + up + `"}
		]}`
		cfg, f := ParseConfig([]byte(src))
		if f == nil || f.Code != "invalid_config" {
			t.Fatalf("upstream %q: got %+v, want invalid_config", up, f)
		}
		if cfg != nil {
			t.Fatalf("upstream %q: a rejected config must not be returned", up)
		}
	}
}

func TestResolveValidIPv6Upstreams(t *testing.T) {
	// Full, compressed and IPv4-tail forms are legal, as are a port,
	// percent-encoded userinfo and a percent-encoded zone. Validation must
	// not re-encode or otherwise alter the configured bytes: joining slices
	// the raw upstream, so every legal spelling reaches upstreamURL byte for
	// byte.
	cases := []struct {
		name     string
		upstream string
		target   string
		want     string
	}{
		{
			name:     "full form",
			upstream: "http://[2001:0db8:0000:0000:0000:0000:0000:0001]/b",
			target:   "/x",
			want:     "http://[2001:0db8:0000:0000:0000:0000:0000:0001]/b/x",
		},
		{
			name:     "compressed form",
			upstream: "http://[2001:db8::1]/b",
			target:   "/x",
			want:     "http://[2001:db8::1]/b/x",
		},
		{
			name:     "embedded ipv4 tail with port",
			upstream: "http://[::ffff:192.168.0.1]:8080/b",
			target:   "/x",
			want:     "http://[::ffff:192.168.0.1]:8080/b/x",
		},
		{
			name:     "userinfo, port and encoded base path",
			upstream: "https://user:p%40ss@[2001:db8::1]:8443/v%2f",
			target:   "/api/orders?a=1&a=",
			want:     "https://user:p%40ss@[2001:db8::1]:8443/v%2f/orders?a=1&a=",
		},
		{
			name:     "percent encoded zone keeps its original spelling",
			upstream: "https://[fe80::1%25eth0]/base",
			target:   "/x?z=1",
			want:     "https://[fe80::1%25eth0]/base/x?z=1",
		},
		{
			name:     "uppercase hex groups",
			upstream: "http://[2001:DB8::ABCD]/b",
			target:   "/x",
			want:     "http://[2001:DB8::ABCD]/b/x",
		},
		{
			name:     "userinfo, port, encoded base path and encoded slash query all stay verbatim",
			upstream: "https://user:p%40ss@[2001:DB8::1]:8443/v%2f",
			target:   "/api/x?q=%2f",
			want:     "https://user:p%40ss@[2001:DB8::1]:8443/v%2f/x?q=%2f",
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			prefix := "/"
			if strings.HasPrefix(tc.target, "/api") {
				prefix = "/api"
			}
			src := `{"routes":[{"id":"r","methods":["GET"],"pathPrefix":"` + prefix +
				`","upstream":"` + tc.upstream + `"}]}`
			cfg := mustConfig(t, src)
			res := resolveJSON(t, cfg, `{"method":"GET","target":"`+tc.target+`"}`)
			if res.RouteID != "r" {
				t.Errorf("routeId = %q, want r", res.RouteID)
			}
			if res.UpstreamURL != tc.want {
				t.Errorf("upstreamURL = %q, want %q", res.UpstreamURL, tc.want)
			}
		})
	}
}

func TestInvalidConfigUnbracketedIPv6Host(t *testing.T) {
	// An IPv6 literal is an IP-literal and must be wrapped in one pair of
	// square brackets; a bare literal leaves the host/port boundary undefined
	// (with "::1:8080" the reader cannot tell the host from a port) and the
	// reader never inserts brackets or guesses a port. Every IPv6 spelling
	// rejects the whole configuration as invalid_config with a content reason
	// naming the route's 1-based position, its id and the upstream field — a
	// digit at the end never makes the spelling legal, and this is never a
	// broken-JSON failure.
	badUpstreams := []struct {
		name     string
		upstream string
	}{
		{"compressed address under base path", "http://2001:db8::1/base"},
		{"compressed address with trailing digits", "http://::1:8080/base"},
		{"embedded ipv4 tail", "http://::ffff:192.0.2.1/base"},
		{"full form", "http://2001:0db8:0000:0000:0000:0000:0000:0001/base"},
		{"loopback with no base path", "http://::1"},
		{"address and trailing digits, no base path", "http://fe80::1:8080"},
		{"percent encoded zone without brackets", "http://fe80::1%25eth0/base"},
		{"userinfo before a bare literal", "http://user:pw@2001:db8::1/base"},
		{"encoded userinfo and a port-like suffix", "https://user:p%40ss@2001:db8::1:8443/base"},
	}
	for _, tc := range badUpstreams {
		t.Run(tc.name, func(t *testing.T) {
			src := `{"routes":[
			  {"id":"api","methods":["GET"],"pathPrefix":"/api","upstream":"http://api.internal/v1"},
			  {"id":"admin","methods":["GET"],"pathPrefix":"/admin","upstream":"` + tc.upstream + `"}
			]}`
			cfg, f := ParseConfig([]byte(src))
			if f == nil {
				t.Fatalf("expected invalid_config for upstream %q", tc.upstream)
			}
			if f.Code != "invalid_config" {
				t.Fatalf("code = %q, want invalid_config", f.Code)
			}
			for _, want := range []string{"route 2", `"admin"`, "upstream", "IPv6", "bracket"} {
				if !strings.Contains(f.Reason, want) {
					t.Fatalf("reason = %q, want substring %q", f.Reason, want)
				}
			}
			if strings.Contains(f.Reason, "not valid JSON") {
				t.Fatalf("an unbracketed IPv6 host is a content error, not a JSON syntax failure: %q", f.Reason)
			}
			if cfg != nil {
				t.Fatalf("a rejected config must not be returned, got %+v", cfg)
			}
		})
	}

	// The offending route may be one the request never hits: config
	// validation still fails up front (and hands back no config at all)
	// instead of letting the first, valid route resolve the request.
	for _, up := range []string{"http://2001:db8::1/base", "http://::1:8080/base", "http://::ffff:192.0.2.1/base"} {
		src := `{"routes":[
		  {"id":"api","methods":["GET"],"pathPrefix":"/api","upstream":"http://api.internal/v1"},
		  {"id":"admin","methods":["GET"],"pathPrefix":"/admin","upstream":"` + up + `"}
		]}`
		cfg, f := ParseConfig([]byte(src))
		if f == nil || f.Code != "invalid_config" {
			t.Fatalf("upstream %q: got %+v, want invalid_config", up, f)
		}
		if cfg != nil {
			t.Fatalf("upstream %q: a rejected config must not be returned", up)
		}
	}
}

func TestUnbracketedNonIPv6AuthoritiesUnaffected(t *testing.T) {
	// Ordinary domains and bare IPv4 hosts keep their existing behavior with
	// or without a port, and colons inside userinfo or the base path must not
	// turn a legal host into a flagged IPv6 literal. Each upstream must both
	// parse and join the remainder byte for byte.
	cases := []struct {
		name     string
		upstream string
		target   string
		want     string
	}{
		{"plain domain", "http://api.internal/v1", "/x", "http://api.internal/v1/x"},
		{"domain with port", "http://api.internal:8080/v1", "/x", "http://api.internal:8080/v1/x"},
		{"bare ipv4", "http://192.0.2.1/base", "/x", "http://192.0.2.1/base/x"},
		{"bare ipv4 with port", "http://192.0.2.1:8080/base", "/x", "http://192.0.2.1:8080/base/x"},
		{"colon in userinfo", "http://user:pa:ss@h.internal:8080/base", "/x", "http://user:pa:ss@h.internal:8080/base/x"},
		{"colon in base path", "http://h.internal/base/a:b/c", "/x", "http://h.internal/base/a:b/c/x"},
		{"localhost without port", "http://localhost/base", "/x", "http://localhost/base/x"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			src := `{"routes":[{"id":"r","methods":["GET"],"pathPrefix":"/","upstream":"` + tc.upstream + `"}]}`
			cfg := mustConfig(t, src)
			res := resolveJSON(t, cfg, `{"method":"GET","target":"`+tc.target+`"}`)
			if res.RouteID != "r" {
				t.Errorf("routeId = %q, want r", res.RouteID)
			}
			if res.UpstreamURL != tc.want {
				t.Errorf("upstreamURL = %q, want %q", res.UpstreamURL, tc.want)
			}
		})
	}
}

func TestInvalidConfigUnbracketedHostExtraColon(t *testing.T) {
	// An unbracketed host part may carry at most the one colon that
	// separates the host from its port. Two or more colons are illegal
	// regardless of their content: a numeric last segment never becomes a
	// guessed port, a malformed IPv6-shaped spelling is not rescued because
	// it resembles an address, and a base path changes nothing. Each such
	// upstream rejects the whole configuration as invalid_config — a content
	// error in legal JSON, never a JSON syntax failure — with a reason
	// naming the route's 1-based position, its id and the upstream field and
	// stating the unbracketed host part carries an extra colon.
	badUpstreams := []struct {
		name     string
		upstream string
	}{
		{"name part, name part and digits under a base path", "http://api:internal:8080/base"},
		{"name part, name part and digits without a base path", "http://api:internal:8080"},
		{"name part and two digit segments", "http://name:part:80"},
		{"malformed ipv6 shaped spelling with triple colon", "http://2001:db8:::1/base"},
		{"nine all numeric groups are not a legal ipv6 host", "http://1:2:3:4:5:6:7:8:9"},
		{"colon name with a path and no digits at the end", "http://a:b:c/base"},
		{"colons in userinfo plus an extra colon after the at sign", "https://user:pa:ss@api:internal:8080/base"},
		{"extra colon after userinfo without a base path", "http://u:p@host:part:80"},
		{"https name with two separators", "https://svc:name:8443"},
	}
	for _, tc := range badUpstreams {
		t.Run(tc.name, func(t *testing.T) {
			src := `{"routes":[
			  {"id":"api","methods":["GET"],"pathPrefix":"/api","upstream":"http://api.internal/v1"},
			  {"id":"admin","methods":["GET"],"pathPrefix":"/admin","upstream":"` + tc.upstream + `"}
			]}`
			cfg, f := ParseConfig([]byte(src))
			if f == nil {
				t.Fatalf("expected invalid_config for upstream %q", tc.upstream)
			}
			if f.Code != "invalid_config" {
				t.Fatalf("code = %q, want invalid_config", f.Code)
			}
			for _, want := range []string{"route 2", `"admin"`, "upstream", "more than one colon"} {
				if !strings.Contains(f.Reason, want) {
					t.Fatalf("reason = %q, want substring %q", f.Reason, want)
				}
			}
			if strings.Contains(f.Reason, "not valid JSON") {
				t.Fatalf("an extra-colon host is a content error, not a JSON syntax failure: %q", f.Reason)
			}
			if strings.Contains(f.Reason, "invalid port") {
				t.Fatalf("the reason must name the extra colon, not a generic url.Parse port error: %q", f.Reason)
			}
			if cfg != nil {
				t.Fatalf("a rejected config must not be returned, got %+v", cfg)
			}
		})
	}

	// The offending route can be the only route, and it still fails even
	// though a request is never resolved against it: config validation owns
	// the rule up front.
	only := `{"routes":[{"id":"api","methods":["GET"],"pathPrefix":"/api","upstream":"http://api:internal:8080/base"}]}`
	if cfg, f := ParseConfig([]byte(only)); f == nil || f.Code != "invalid_config" {
		t.Fatalf("single-route multi-colon upstream: got cfg=%+v f=%+v, want invalid_config", cfg, f)
	} else if !strings.Contains(f.Reason, "route 1") || !strings.Contains(f.Reason, `"api"`) {
		t.Fatalf("reason = %q, want route 1 and id \"api\"", f.Reason)
	}

	// A bad later route rejects the config even when a request would only
	// ever hit the valid first route.
	src := `{"routes":[
	  {"id":"api","methods":["GET"],"pathPrefix":"/api","upstream":"http://api.internal/v1"},
	  {"id":"admin","methods":["GET"],"pathPrefix":"/admin","upstream":"http://name:part:80/base"}
	]}`
	cfg, f := ParseConfig([]byte(src))
	if f == nil || f.Code != "invalid_config" {
		t.Fatalf("got cfg=%+v f=%+v, want invalid_config", cfg, f)
	}
	if cfg != nil {
		t.Fatalf("a rejected config must not be returned")
	}
}

func TestUnbracketedExtraColonRuleDoesNotMisfire(t *testing.T) {
	// The rule is confined to hostPort — the authority after the last '@'
	// and before the first path slash — so colons that belong to userinfo or
	// the base path, a percent-encoded colon in the host, and every ordinary
	// domain / IPv4 / single-port spelling must keep parsing and joining
	// byte for byte.
	cases := []struct {
		name     string
		upstream string
		target   string
		want     string
	}{
		{"colons in both userinfo and base path", "http://user:pa:ss@api.internal:8080/base/a:b", "/x", "http://user:pa:ss@api.internal:8080/base/a:b/x"},
		{"many colons in userinfo only", "http://a:b:c:d@h.internal:80/b", "/x", "http://a:b:c:d@h.internal:80/b/x"},
		{"colon only in the base path", "http://h.internal/base/a:b", "/x", "http://h.internal/base/a:b/x"},
		{"plain domain", "http://api.internal/v1", "/x", "http://api.internal/v1/x"},
		{"domain with one port colon", "http://api.internal:8080/v1", "/x", "http://api.internal:8080/v1/x"},
		{"bare ipv4", "http://192.0.2.1/base", "/x", "http://192.0.2.1/base/x"},
		{"ipv4 with port", "http://192.0.2.1:8080/base", "/x", "http://192.0.2.1:8080/base/x"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			src := `{"routes":[{"id":"r","methods":["GET"],"pathPrefix":"/","upstream":"` + tc.upstream + `"}]}`
			cfg := mustConfig(t, src)
			res := resolveJSON(t, cfg, `{"method":"GET","target":"`+tc.target+`"}`)
			if res.RouteID != "r" {
				t.Errorf("routeId = %q, want r", res.RouteID)
			}
			if res.UpstreamURL != tc.want {
				t.Errorf("upstreamURL = %q, want %q", res.UpstreamURL, tc.want)
			}
		})
	}
}

func TestInvalidConfigUpstreamMissingHost(t *testing.T) {
	// Every upstream must carry a genuinely non-empty host. url.Parse itself
	// accepts a leading port colon with an empty hostname ("http://:8080/base"
	// parses with Host==":8080" and Hostname()==""), so the rule is enforced
	// on the raw splitUpstream boundaries: a hostPort that is empty or begins
	// with the port colon rejects the whole configuration as invalid_config,
	// whether the missing host leaves just a port, just userinfo or nothing
	// at all. The reason names the route's 1-based position, its id and the
	// upstream field and says the upstream is missing a host — it is a content
	// error in legal JSON, never a JSON parse failure and never an
	// IPv6-missing-brackets complaint.
	badUpstreams := []struct {
		name     string
		upstream string
	}{
		{"bare port under a base path", "http://:8080/base"},
		{"bare port without a base path", "https://:8443"},
		{"empty port under a base path", "http://:/base"},
		{"encoded userinfo before a bare port", "https://user:p%40ss@:8443/v1"},
		{"plain userinfo before a bare port", "http://user:pass@:8080/base"},
		{"empty authority before a base path", "http:///base"},
		{"userinfo reduced to an empty authority", "http://u@/base"},
		{"userinfo with an empty port and no host", "http://a:b@:/base"},
	}
	for _, tc := range badUpstreams {
		t.Run(tc.name, func(t *testing.T) {
			src := `{"routes":[
			  {"id":"api","methods":["GET"],"pathPrefix":"/api","upstream":"http://api.internal/v1"},
			  {"id":"admin","methods":["GET"],"pathPrefix":"/admin","upstream":"` + tc.upstream + `"}
			]}`
			cfg, f := ParseConfig([]byte(src))
			if f == nil {
				t.Fatalf("expected invalid_config for upstream %q", tc.upstream)
			}
			if f.Code != "invalid_config" {
				t.Fatalf("code = %q, want invalid_config", f.Code)
			}
			for _, want := range []string{"route 2", `"admin"`, "upstream", "missing a host"} {
				if !strings.Contains(f.Reason, want) {
					t.Fatalf("reason = %q, want substring %q", f.Reason, want)
				}
			}
			for _, forbidden := range []string{"not valid JSON", "bracket"} {
				if strings.Contains(f.Reason, forbidden) {
					t.Fatalf("reason = %q must not say %q: an empty host is an address-content error",
						f.Reason, forbidden)
				}
			}
			if cfg != nil {
				t.Fatalf("a rejected config must not be returned, got %+v", cfg)
			}
		})
	}

	// The offending route may be the only route: validation fails while the
	// config is read, before any request reaches Resolve.
	for _, up := range []string{"http://:8080/base", "https://:8443", "http://:/base",
		"https://user:p%40ss@:8443/v1"} {
		src := `{"routes":[{"id":"api","methods":["GET"],"pathPrefix":"/api","upstream":"` + up + `"}]}`
		cfg, f := ParseConfig([]byte(src))
		if f == nil || f.Code != "invalid_config" {
			t.Fatalf("upstream %q: got cfg=%+v f=%+v, want invalid_config", up, cfg, f)
		}
		if !strings.Contains(f.Reason, "route 1") || !strings.Contains(f.Reason, `"api"`) {
			t.Fatalf("upstream %q: reason = %q, want route 1 and id \"api\"", up, f.Reason)
		}
	}

	// A later hostless route rejects the config even when a request would
	// only hit the first, valid route: ParseConfig hands back no config at
	// all, so the request can never resolve against the earlier route.
	src := `{"routes":[
	  {"id":"api","methods":["GET"],"pathPrefix":"/api","upstream":"http://api.internal/v1"},
	  {"id":"admin","methods":["GET"],"pathPrefix":"/admin","upstream":"http://:8080/base"}
	]}`
	cfg, f := ParseConfig([]byte(src))
	if f == nil || f.Code != "invalid_config" {
		t.Fatalf("got cfg=%+v f=%+v, want invalid_config", cfg, f)
	}
	if cfg != nil {
		t.Fatal("a rejected config must not be returned")
	}
}

func TestEmptyPortWithHostStillAccepted(t *testing.T) {
	// The missing-host rule judges whether anything was written before the
	// port colon, not whether the port itself is filled: a host followed by
	// an empty port keeps its existing behavior, and the base path is still
	// joined byte for byte.
	cases := []struct {
		name     string
		upstream string
		target   string
		want     string
	}{
		{"host with an empty port under a base path", "http://api.internal:/base", "/x", "http://api.internal:/base/x"},
		{"host with an empty port and no base path", "http://api.internal:", "/x", "http://api.internal:/x"},
		{"userinfo, host and an empty port", "https://u:p@api.internal:/b", "/x", "https://u:p@api.internal:/b/x"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			src := `{"routes":[{"id":"r","methods":["GET"],"pathPrefix":"/","upstream":"` + tc.upstream + `"}]}`
			cfg := mustConfig(t, src)
			res := resolveJSON(t, cfg, `{"method":"GET","target":"`+tc.target+`"}`)
			if res.RouteID != "r" {
				t.Errorf("routeId = %q, want r", res.RouteID)
			}
			if res.UpstreamURL != tc.want {
				t.Errorf("upstreamURL = %q, want %q", res.UpstreamURL, tc.want)
			}
		})
	}
}

func TestInvalidConfigUpstreamPercentEscape(t *testing.T) {
	// A malformed percent escape anywhere in the upstream URL rejects the
	// whole configuration as invalid_config, and the reason locates the
	// offending route by position and id even when an earlier route is fine.
	cases := []struct {
		name     string
		upstream string
	}{
		{"bad hex in path", "http://h.internal/base%zz/x"},
		{"truncated escape at end of path", "http://h.internal/base%2"},
		{"lone percent in path", "http://h.internal/base%/x"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			src := `{"routes":[
			  {"id":"api","methods":["GET"],"pathPrefix":"/api","upstream":"http://api.internal/v1"},
			  {"id":"admin","methods":["GET"],"pathPrefix":"/admin","upstream":"` + tc.upstream + `"}
			]}`
			_, f := ParseConfig([]byte(src))
			if f == nil {
				t.Fatalf("expected invalid_config for upstream %q", tc.upstream)
			}
			if f.Code != "invalid_config" {
				t.Fatalf("code = %q, want invalid_config", f.Code)
			}
			for _, want := range []string{"route 2", `"admin"`, "upstream"} {
				if !strings.Contains(f.Reason, want) {
					t.Fatalf("reason = %q, want substring %q", f.Reason, want)
				}
			}
		})
	}
}

func TestResolveSegmentBoundary(t *testing.T) {
	cfg := mustConfig(t, sampleConfig)

	// /api must not match /apiv2; it falls through to the root route.
	res := resolveJSON(t, cfg, `{"method":"GET","target":"/apiv2/x"}`)
	if res.RouteID != "root" {
		t.Fatalf("routeId = %q, want root", res.RouteID)
	}
	if want := "https://fallback.internal/base/apiv2/x"; res.UpstreamURL != want {
		t.Errorf("upstreamURL = %q, want %q", res.UpstreamURL, want)
	}

	// "%2F" is an encoded slash in the remainder, never a segment separator.
	res = resolveJSON(t, cfg, `{"method":"GET","target":"/api%2Fv2/secret"}`)
	if res.RouteID != "root" {
		t.Fatalf("routeId = %q, want root (encoded slash is not a boundary)", res.RouteID)
	}
}

func TestResolveConcreteMethodBeatsWildcard(t *testing.T) {
	cfg := mustConfig(t, `{
	  "routes": [
	    {"id": "wide",   "methods": ["*"],  "pathPrefix": "/things", "upstream": "http://wide.internal"},
	    {"id": "exact",  "methods": ["GET"],"pathPrefix": "/things", "upstream": "http://exact.internal"}
	  ]
	}`)

